    explanation: '第4類の危険物は、液体そのものではなく液面から発生する蒸気が空気と混ざって燃える。したがって蒸気を外に出さないことが火災予防の出発点であり、容器の密栓はその最も基本的な手段である。ふたを開けたままにすると蒸気が室内へ漏れ、床面をはって滞留し、離れた場所の火気で引火する。また密栓は水分の混入や不純物の侵入、揮発による品質低下を防ぐ効果もある。ただし液体は温度で膨張するため、容器には空間容積を残しておく。\n【図解】容器の取扱いの基本\n　項目｜正しい方法｜理由\n　ふた｜必ず密栓する｜蒸気の漏えいを防ぐ\n　充てん量｜空間容積を残す｜膨張による破損を防ぐ\n　保管場所｜直射日光を避けた冷所｜液温上昇を防ぐ\n　転倒防止｜安定した場所に置く｜漏えい事故を防ぐ\n　⇒ 蒸気を出さない、液温を上げない、こぼさないが三原則\n　⚠ 密栓しても膨張の余地がなければ容器が変形または破損する',
