    correctKey: 'B',
    explanation: '泡消火剤は液面を覆うことで消火するため、泡の層を壊さないように放射することが肝心である。燃えている液面に直接たたきつけると、泡が油の中に沈み込んで層をつくれないうえ、液面をかき乱して油を飛散させる。そこでタンクの内壁に沿わせて流し込む、あるいは液面に静かに広がるように放射するのが原則である。あわせて泡の層は十分な厚さを確保し、消火後も泡層を維持して再燃を防ぐ。放射は風上から行い、退路を確保しておく。\n【図解】泡放射の要点\n　項目｜正しい方法｜避けるべき方法\n　放射方向｜内壁に沿わせて静かに｜液面へ強くたたきつける\n　泡層｜十分な厚さを確保｜薄い層で早く切り上げる\n　位置｜風上から放射する｜風下から接近する\n　消火後｜泡層を維持する｜すぐに泡を止める\n　⇒ 泡は覆うための道具であり、勢いで消すものではない\n　⚠ 泡層が消えると高温の液面から再燃するおそれがある',
